39 | <style>
40 | .bento-container[data-bento-grid] {
41 |     --grid-gap: 2rem;
42 |     --bento-radius: 1.5rem;
43 |     display: grid;
44 |     gap: var(--grid-gap);
45 |     padding: var(--grid-gap);
46 | }
47 | .bento-item {
48 |     border-radius: var(--bento-radius);
49 |     overflow: hidden;
